"use strict";

const path = require("node:path");

const CANONICAL_FIXTURE_IDS = Object.freeze([
  "benign-maintenance-001",
  "mild-urgency-001",
  "obfuscated-relay-001",
  "wallet-risk-001",
  "credential-risk-001",
  "fake-support-001",
  "scanner-failure-001"
]);

const ALLOWED_LANES = new Set(["clear", "low", "medium", "high", "critical"]);
const ALLOWED_CATEGORIES = new Set([
  "credential_phish",
  "drain_phrase",
  "encoded_instruction_relay",
  "external_wallet",
  "fake_support",
  "fund_transfer",
  "malformed_url",
  "obfuscation",
  "prompt_injection",
  "reward_claim",
  "secret_request",
  "shortened_url",
  "unicode_url",
  "unknown_financial_domain",
  "urgent_pressure"
]);
const ALLOWED_ERROR_CLASSES = new Set([
  "input_invalid",
  "fixture_missing",
  "scanner_failure",
  "output_invalid",
  "incomplete_run"
]);
const INPUT_KEYS = new Set(["fixtureId", "expectedLane", "sourceRef", "expectedCategories"]);
const OUTPUT_KEYS = new Set([
  "fixtureId",
  "expectedLane",
  "actualLane",
  "match",
  "categories",
  "decision",
  "errorClass"
]);

function error(errorClass, field, fixtureId) {
  const item = { errorClass };
  if (field) item.field = field;
  if (CANONICAL_FIXTURE_IDS.includes(fixtureId)) item.fixtureId = fixtureId;
  return item;
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function hasOnlyKeys(record, allowed) {
  return Object.keys(record).every((key) => allowed.has(key));
}

function isUniqueAllowedList(value, allowed) {
  return Array.isArray(value)
    && new Set(value).size === value.length
    && value.every((item) => typeof item === "string" && allowed.has(item));
}

function isSafeSourceRef(value) {
  if (typeof value !== "string" || value.length === 0 || value.includes("\0")) return false;
  if (/^[a-z][a-z0-9+.-]*:/i.test(value) || value.startsWith("//")) return false;
  if (path.posix.isAbsolute(value) || path.win32.isAbsolute(value) || value.includes("\\")) return false;
  return !value.split("/").includes("..");
}

function validateManifest(manifest) {
  const errors = [];
  if (!Array.isArray(manifest)) return { valid: false, errors: [error("input_invalid", "manifest")] };
  if (manifest.length !== CANONICAL_FIXTURE_IDS.length) {
    errors.push(error("incomplete_run", "manifest"));
  }

  const seen = new Set();
  for (const record of manifest) {
    if (!isPlainObject(record)) {
      errors.push(error("input_invalid", "record"));
      continue;
    }

    const fixtureId = record.fixtureId;
    if (!hasOnlyKeys(record, INPUT_KEYS)) errors.push(error("input_invalid", "record", fixtureId));
    if (!CANONICAL_FIXTURE_IDS.includes(fixtureId)) {
      errors.push(error("input_invalid", "fixtureId"));
    } else if (seen.has(fixtureId)) {
      errors.push(error("input_invalid", "fixtureId", fixtureId));
    } else {
      seen.add(fixtureId);
    }

    if (!ALLOWED_LANES.has(record.expectedLane)) {
      errors.push(error("input_invalid", "expectedLane", fixtureId));
    }
    if (!isSafeSourceRef(record.sourceRef)) {
      errors.push(error("input_invalid", "sourceRef", fixtureId));
    }
    if (!isUniqueAllowedList(record.expectedCategories, ALLOWED_CATEGORIES)) {
      errors.push(error("input_invalid", "expectedCategories", fixtureId));
    }
  }

  if (seen.size !== CANONICAL_FIXTURE_IDS.length) {
    errors.push(error("incomplete_run", "fixtureId"));
  }
  return { valid: errors.length === 0, errors };
}

function validateOutput(records) {
  const errors = [];
  if (!Array.isArray(records)) return { valid: false, errors: [error("output_invalid", "records")] };
  if (records.length !== CANONICAL_FIXTURE_IDS.length) {
    errors.push(error("incomplete_run", "records"));
  }

  const seen = new Set();
  records.forEach((record, index) => {
    if (!isPlainObject(record)) {
      errors.push(error("output_invalid", "record"));
      return;
    }

    const fixtureId = record.fixtureId;
    if (!hasOnlyKeys(record, OUTPUT_KEYS)) errors.push(error("output_invalid", "record", fixtureId));
    if (!CANONICAL_FIXTURE_IDS.includes(fixtureId)) {
      errors.push(error("output_invalid", "fixtureId"));
    } else {
      if (seen.has(fixtureId)) errors.push(error("output_invalid", "fixtureId", fixtureId));
      seen.add(fixtureId);
      if (CANONICAL_FIXTURE_IDS[index] !== fixtureId) {
        errors.push(error("output_invalid", "order", fixtureId));
      }
    }

    if (!ALLOWED_LANES.has(record.expectedLane)) errors.push(error("output_invalid", "expectedLane", fixtureId));
    if (!ALLOWED_LANES.has(record.actualLane)) errors.push(error("output_invalid", "actualLane", fixtureId));
    if (typeof record.match !== "boolean") errors.push(error("output_invalid", "match", fixtureId));
    if (!isUniqueAllowedList(record.categories, ALLOWED_CATEGORIES)) {
      errors.push(error("output_invalid", "categories", fixtureId));
    }
    if (record.decision !== "keep" && record.decision !== "hold") {
      errors.push(error("output_invalid", "decision", fixtureId));
    }
    if (record.errorClass !== undefined && !ALLOWED_ERROR_CLASSES.has(record.errorClass)) {
      errors.push(error("output_invalid", "errorClass", fixtureId));
    }

    const lanesMatch = ALLOWED_LANES.has(record.expectedLane)
      && ALLOWED_LANES.has(record.actualLane)
      && record.expectedLane === record.actualLane;
    if (typeof record.match === "boolean" && record.match !== lanesMatch) {
      errors.push(error("output_invalid", "match", fixtureId));
    }
    if (record.errorClass !== undefined && (record.match !== false || record.decision !== "hold")) {
      errors.push(error("output_invalid", "errorClass", fixtureId));
    } else if (record.errorClass === undefined && typeof record.match === "boolean") {
      const expectedDecision = record.match ? "keep" : "hold";
      if (record.decision !== expectedDecision) errors.push(error("output_invalid", "decision", fixtureId));
    }
  });

  if (seen.size !== CANONICAL_FIXTURE_IDS.length) {
    errors.push(error("incomplete_run", "fixtureId"));
  }
  return { valid: errors.length === 0, errors };
}

module.exports = {
  CANONICAL_FIXTURE_IDS,
  validateManifest,
  validateOutput
};

"use strict";

const { describe, it } = require("node:test");
const assert = require("node:assert/strict");
const {
  CANONICAL_FIXTURE_IDS,
  validateManifest,
  validateOutput
} = require("../packages/issue-scam-scanner/calibration-validator");

const lanes = ["clear", "low", "medium", "high", "critical", "critical", "clear"];

function validManifest() {
  return CANONICAL_FIXTURE_IDS.map((fixtureId, index) => ({
    fixtureId,
    expectedLane: lanes[index],
    sourceRef: `tests/fixtures/${fixtureId}.txt`,
    expectedCategories: []
  }));
}

function validOutput() {
  return CANONICAL_FIXTURE_IDS.map((fixtureId, index) => ({
    fixtureId,
    expectedLane: lanes[index],
    actualLane: lanes[index],
    match: true,
    categories: [],
    decision: "keep"
  }));
}

describe("calibration validator", () => {
  it("accepts the exact canonical manifest", () => {
    assert.deepEqual(validateManifest(validManifest()), { valid: true, errors: [] });
  });

  it("rejects missing, duplicate, unknown, and unsafe manifest values without echoing them", () => {
    const manifest = validManifest();
    manifest.pop();
    manifest[1] = { ...manifest[0] };
    manifest[2] = { ...manifest[2], fixtureId: "unknown-fixture" };
    manifest[3] = { ...manifest[3], expectedLane: "unknown-lane" };
    manifest[4] = { ...manifest[4], expectedCategories: ["unknown-category"] };
    manifest[5] = { ...manifest[5], sourceRef: "https://example.invalid/fixture" };

    const result = validateManifest(manifest);
    assert.equal(result.valid, false);
    assert.ok(result.errors.some((item) => item.errorClass === "incomplete_run"));
    assert.ok(result.errors.some((item) => item.field === "sourceRef"));
    assert.equal(JSON.stringify(result).includes("example.invalid"), false);
    assert.equal(JSON.stringify(result).includes("unknown-category"), false);
  });

  it("rejects absolute and traversing source references", () => {
    for (const sourceRef of ["../fixture.txt", "/tmp/fixture.txt", "C:\\temp\\fixture.txt"]) {
      const manifest = validManifest();
      manifest[0] = { ...manifest[0], sourceRef };
      assert.equal(validateManifest(manifest).valid, false);
    }
  });

  it("accepts canonical public-safe output", () => {
    assert.deepEqual(validateOutput(validOutput()), { valid: true, errors: [] });
  });

  it("accepts a completed lane mismatch only with hold", () => {
    const records = validOutput();
    records[1] = { ...records[1], actualLane: "medium", match: false, decision: "hold" };
    assert.equal(validateOutput(records).valid, true);
  });

  it("rejects extra fields, wrong order, inconsistent match, and fabricated failure success", () => {
    const records = validOutput();
    records[0] = { ...records[0], rawBody: "must-not-pass" };
    [records[1], records[2]] = [records[2], records[1]];
    records[3] = { ...records[3], actualLane: "low" };
    records[4] = { ...records[4], errorClass: "scanner_failure" };

    const result = validateOutput(records);
    assert.equal(result.valid, false);
    assert.ok(result.errors.some((item) => item.field === "record"));
    assert.ok(result.errors.some((item) => item.field === "order"));
    assert.ok(result.errors.some((item) => item.field === "match"));
    assert.ok(result.errors.some((item) => item.field === "errorClass"));
    assert.equal(JSON.stringify(result).includes("must-not-pass"), false);
  });
});

#!/usr/bin/env node
/**
 * Orbit CLI — Query Orbit's state from the command line.
 *
 * Usage:
 *   orbit status [--repo /path/to/repo]
 *   orbit budget [--repo /path/to/repo]
 *   orbit capabilities [--repo /path/to/repo]
 *   orbit tasks [--repo /path/to/repo]
 *   orbit blocked [--repo /path/to/repo]
 *   orbit opportunities [--repo /path/to/repo] [--limit 5]
 *   orbit latest-cycle [--repo /path/to/repo]
 *   orbit health [--repo /path/to/repo]
 *   orbit files [--repo /path/to/repo]
 *
 * Cycle 481 direction choice:
 * - Compared build (scanner prototype), earn (agent passport), maintain (open
 *   CLI safety task), and infrastructure (control-plane growth).
 * - Selected maintain because removing detailed AI-budget fields from the
 *   public status command is the smallest live safety obligation and unblocks
 *   later calibration work without expanding execution authority.
 */

const { create } = require('./index');

function parseArgs(argv) {
  const args = { command: null, repo: process.cwd(), limit: 5 };
  let i = 2;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg === '--repo' || arg === '-r') {
      args.repo = argv[++i];
    } else if (arg === '--limit' || arg === '-l') {
      args.limit = parseInt(argv[++i], 10) || 5;
    } else if (arg === '--help' || arg === '-h') {
      args.command = 'help';
    } else if (!args.command) {
      args.command = arg;
    }
    i++;
  }
  return args;
}

function printJson(obj) {
  console.log(JSON.stringify(obj, null, 2));
}

function budgetLevel(summary) {
  if (!summary || summary.canUseAi === false) return 'exhausted';

  const dailyLimit = Number(summary.dailyBudgetUsd || 0);
  const monthlyLimit = Number(summary.monthlyBudgetUsd || 0);
  const dailyRemaining = Number(summary.dailyRemainingUsd || 0);
  const monthlyRemaining = Number(summary.monthlyRemainingUsd || 0);

  const ratios = [];
  if (dailyLimit > 0) ratios.push(dailyRemaining / dailyLimit);
  if (monthlyLimit > 0) ratios.push(monthlyRemaining / monthlyLimit);
  const lowestRatio = ratios.length ? Math.min(...ratios) : 1;

  if (lowestRatio <= 0) return 'exhausted';
  if (lowestRatio <= 0.1) return 'critical';
  if (lowestRatio <= 0.25) return 'low';
  return 'ok';
}

function publicBudgetSummary(sdk) {
  const summary = sdk.budgetSummary();
  return {
    status: budgetLevel(summary),
    canUseAi: Boolean(summary.canUseAi),
    policy: 'public_safe_status_only',
    note: 'Detailed inference spend and remaining budget amounts are intentionally omitted from CLI output.',
  };
}

function publicStatusSummary(sdk) {
  const status = sdk.quickStatus();
  return {
    cycle: status.cycle,
    born: status.born,
    lastActive: status.lastActive,
    lastStatus: status.lastStatus,
    currentLevel: status.currentLevel,
    currentLevelStatus: status.currentLevelStatus,
    activeLane: status.activeLane,
    openTaskCount: status.openTaskCount,
    completedTaskCount: status.completedTaskCount,
    aiBudget: publicBudgetSummary(sdk),
  };
}

function help() {
  console.log(`
Orbit CLI — Query Orbit's machine-readable state.

Commands:
  status          Quick status summary (cycle, level, tasks, budget status)
  budget          Public-safe AI-call budget status only
  capabilities    Active and planned capabilities
  tasks           Open and blocked tasks
  blocked         Wallet and external action restrictions
  opportunities   Top earning opportunities by score
  latest-cycle    Most recent cycle note
  health          Verify that expected files exist and are parseable
  files           List all machine-readable file paths

Options:
  --repo, -r      Path to Orbit repo (default: current directory)
  --limit, -l     Number of items to show (default: 5)
  --help, -h      Show this help message

Safety:
  Budget output is intentionally limited to ok/low/critical/exhausted style
  status. Do not publish detailed inference-spend figures, remaining budget
  amounts, provider routes, billing routes, or private operational details.
`.trim());
}

function main() {
  const args = parseArgs(process.argv);

  if (args.command === 'help' || !args.command) {
    help();
    process.exit(args.command ? 0 : 1);
  }

  const sdk = create(args.repo);

  switch (args.command) {
    case 'status':
      printJson(publicStatusSummary(sdk));
      break;

    case 'budget':
      printJson(publicBudgetSummary(sdk));
      break;

    case 'capabilities': {
      const caps = sdk.getCapabilities();
      printJson({
        active: caps.active.map(c => ({ id: c.id, name: c.name, mode: c.mode })),
        planned: caps.planned.map(c => ({ id: c.id, name: c.name, mode: c.mode })),
      });
      break;
    }

    case 'tasks':
      printJson(sdk.getOpenTasks());
      break;

    case 'blocked':
      printJson(sdk.getBlockedActions());
      break;

    case 'opportunities': {
      const opps = sdk.getTopOpportunities(args.limit);
      printJson(opps.map(o => ({
        id: o.id,
        title: o.title,
        score: o.driverAdjustedScore || o.score,
        status: o.status,
        risk: o.risk,
        approvalRequired: o.approvalRequired,
      })));
      break;
    }

    case 'latest-cycle':
      printJson(sdk.getLatestCycle());
      break;

    case 'health':
      printJson(sdk.healthCheck());
      break;

    case 'files':
      printJson(sdk.getFileList());
      break;

    default:
      console.error(`Unknown command: ${args.command}`);
      help();
      process.exit(1);
  }
}

main();

/**
 * Tests for @orbithouse/sdk
 *
 * Uses Node's built-in test runner (node:test).
 * Tests run against the actual Orbit repo state.
 */

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');
const { create, FILES } = require('../packages/orbit-sdk/index');

const REPO_ROOT = path.resolve(__dirname, '..');

describe('Orbit SDK', () => {
  const sdk = create(REPO_ROOT);

  describe('create()', () => {
    it('returns an object with all expected methods', () => {
      const methods = [
        'getState', 'getPassport', 'getGovernance', 'getTreasury',
        'getRoadmap', 'getTasks', 'getKnowledge', 'getInfrastructure',
        'getOpportunities', 'getApprovals', 'getCycles', 'getCycleNotes',
        'quickStatus', 'budgetSummary', 'getCapabilities', 'getOpenTasks',
        'getBlockedActions', 'getLatestCycle', 'getTopOpportunities',
        'healthCheck', 'getFileList',
      ];
      for (const method of methods) {
        assert.equal(typeof sdk[method], 'function', `Missing method: ${method}`);
      }
    });

    it('exposes repoRoot and files metadata', () => {
      assert.equal(typeof sdk.repoRoot, 'string');
      assert.equal(typeof sdk.files, 'object');
    });
  });

  describe('individual file readers', () => {
    it('getState() returns lifecycle state', () => {
      const state = sdk.getState();
      assert.ok(state, 'state.json should exist');
      assert.equal(typeof state.cycle, 'number');
      assert.equal(typeof state.born, 'string');
    });

    it('getPassport() returns agent passport', () => {
      const passport = sdk.getPassport();
      assert.ok(passport, 'passport.json should exist');
      assert.equal(passport.version, 1);
      assert.ok(passport.identity);
      assert.ok(Array.isArray(passport.capabilities));
    });

    it('getGovernance() returns governance policy', () => {
      const gov = sdk.getGovernance();
      assert.ok(gov, 'governance.json should exist');
      assert.equal(typeof gov.policyVersion, 'number');
      assert.ok(gov.externalSpend);
      assert.ok(Array.isArray(gov.hardRules));
    });

    it('getTreasury() returns treasury data', () => {
      const treasury = sdk.getTreasury();
      assert.ok(treasury, 'treasury.json should exist');
      assert.ok(treasury.ai);
      assert.ok(Array.isArray(treasury.ai.ledger));
      assert.ok(treasury.token);
    });

    it('getRoadmap() returns roadmap', () => {
      const roadmap = sdk.getRoadmap();
      assert.ok(roadmap, 'roadmap.json should exist');
      assert.ok(roadmap.currentLevel);
      assert.ok(Array.isArray(roadmap.lanes));
      assert.ok(Array.isArray(roadmap.levels));
    });

    it('getTasks() returns task list', () => {
      const tasks = sdk.getTasks();
      assert.ok(tasks, 'tasks.json should exist');
      assert.ok(Array.isArray(tasks.tasks));
    });

    it('getKnowledge() returns knowledge entries', () => {
      const knowledge = sdk.getKnowledge();
      assert.ok(knowledge, 'knowledge.json should exist');
      assert.ok(Array.isArray(knowledge.entries));
    });

    it('getInfrastructure() returns infrastructure registry', () => {
      const infra = sdk.getInfrastructure();
      assert.ok(infra, 'infrastructure.json should exist');
      assert.ok(infra.product || infra.summary);
    });

    it('getOpportunities() returns opportunity data', () => {
      const opps = sdk.getOpportunities();
      assert.ok(opps, 'opportunities.json should exist');
      assert.ok(Array.isArray(opps.opportunities));
    });

    it('getCycles() returns JSONL entries', () => {
      const cycles = sdk.getCycles();
      assert.ok(Array.isArray(cycles));
    });

    it('getCycleNotes() returns cycle note files', () => {
      const notes = sdk.getCycleNotes();
      assert.ok(Array.isArray(notes));
      assert.ok(notes.length > 0, 'Should have cycle notes');
      assert.ok(notes[0].filename);
      assert.ok(notes[0].content);
    });
  });

  describe('derived views', () => {
    it('quickStatus() returns a summary with expected fields', () => {
      const status = sdk.quickStatus();
      assert.equal(typeof status.cycle, 'number');
      assert.ok(status.cycle > 0);
      assert.equal(typeof status.born, 'string');
      assert.equal(typeof status.lastActive, 'string');
      assert.equal(typeof status.currentLevel, 'string');
      assert.equal(typeof status.openTaskCount, 'number');
      assert.equal(typeof status.completedTaskCount, 'number');
      assert.equal(typeof status.dailyBudgetUsd, 'number');
      assert.equal(typeof status.ledgerEntries, 'number');
    });

    it('budgetSummary() returns spend analysis', () => {
      const budget = sdk.budgetSummary();
      assert.equal(typeof budget.dailyBudgetUsd, 'number');
      assert.equal(typeof budget.monthlyBudgetUsd, 'number');
      assert.equal(typeof budget.spentTodayUsd, 'number');
      assert.equal(typeof budget.spentThisMonthUsd, 'number');
      assert.equal(typeof budget.lifetimeSpendUsd, 'number');
      assert.equal(typeof budget.dailyRemainingUsd, 'number');
      assert.equal(typeof budget.monthlyRemainingUsd, 'number');
      assert.equal(typeof budget.canUseAi, 'boolean');
      assert.ok(budget.lifetimeSpendUsd > 0, 'Should have recorded spend');
    });

